input.content:
/* Orbit CDN · 变更时间线 —— 样式
 * 层级：时间线（dominant） > 选中详情 / 状态回放（primary） > 筛选 / 元信息（supporting）
 */

:root {
  --bg: #10141b;
  --bg-raised: #171d27;
  --bg-hover: #1d2531;
  --line: #273040;
  --line-strong: #35415a;
  --text: #dde4ee;
  --text-dim: #8b96a8;
  --text-faint: #5f6b7e;
  --accent: #4c8dff;
  --accent-soft: rgba(76, 141, 255, 0.16);
  --amber: #d29a3a;
  --teal: #3aa6b9;
  --add: #46b881;
  --modify: #4c8dff;
  --remove: #e0596f;
  --rename: #a07ef0;
  --mono: Consolas, "Cascadia Mono", "SFMono-Regular", Menlo, monospace;
  --radius: 8px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 13px/1.55 "Segoe UI", "Microsoft YaHei", "PingFang SC", sans-serif;
}

#app {
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---------- 顶栏 ---------- */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
  background: var(--bg-raised);
  flex: none;
}

.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }

.brand-mark {
  font-size: 18px;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 6px;
  width: 32px; height: 32px;
  display: grid; place-items: center;
  flex: none;
}

.brand-text h1 { font-size: 15px; margin: 0; font-weight: 600; letter-spacing: 0.2px; }
.brand-text .meta { margin: 1px 0 0; color: var(--text-dim); font-size: 12px; }

.legend { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; justify-content: flex-end; }
.legend-item { display: inline-flex; align-items: center; gap: 5px; color: var(--text-dim); font-size: 12px; }
.legend-sep { width: 1px; height: 14px; background: var(--line-strong); margin: 0 2px; }

.sym {
  font-style: normal;
  font-family: var(--mono);
  font-weight: 700;
  width: 17px; height: 17px;
  border-radius: 4px;
  display: inline-grid; place-items: center;
  font-size: 12px;
  flex: none;
}
.sym.t-add    { color: var(--add);    background: rgba(70, 184, 129, 0.14); }
.sym.t-modify { color: var(--modify); background: rgba(76, 141, 255, 0.14); }
.sym.t-remove { color: var(--remove); background: rgba(224, 89, 111, 0.14); }
.sym.t-rename { color: var(--rename); background: rgba(160, 126, 240, 0.14); }
.sym.b-cause  { color: var(--amber);  background: rgba(210, 154, 58, 0.14); }
.sym.b-effect { color: var(--teal);   background: rgba(58, 166, 185, 0.14); }

/* ---------- 筛选行 ---------- */

.filterbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 8px 18px;
  border-bottom: 1px solid var(--line);
  flex: none;
  flex-wrap: wrap;
}

.chips { display: flex; gap: 6px; }

.chip {
  border: 1px solid var(--line-strong);
  background: transparent;
  color: var(--text-dim);
  border-radius: 999px;
  padding: 3px 12px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.chip:hover { background: var(--bg-hover); color: var(--text); }
.chip[aria-pressed="true"] {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: var(--text);
}

.element-filter { display: inline-flex; align-items: center; gap: 6px; color: var(--text-dim); font-size: 12px; }

.element-filter select {
  background: var(--bg-raised);
  color: var(--text);
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  padding: 3px 8px;
  font: inherit;
  font-size: 12px;
}

.ghost-btn {
  border: 1px solid var(--line-strong);
  background: transparent;
  color: var(--text-dim);
  border-radius: 6px;
  padding: 3px 10px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.ghost-btn:hover { color: var(--text); background: var(--bg-hover); }

.filter-note { margin: 0 0 0 auto; color: var(--text-faint); font-size: 12px; }
.filter-note.warn { color: var(--amber); }

/* ---------- 主工作区 ---------- */

.workspace {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 11fr) minmax(0, 9fr);
  gap: 0;
}

.pane-head {
  padding: 10px 18px 8px;
  border-bottom: 1px solid var(--line);
  flex: none;
}
.pane-head h2 { margin: 0; font-size: 13px; font-weight: 600; }
.pane-sub { color: var(--text-faint); font-weight: 400; font-size: 11px; margin-left: 8px; letter-spacing: 0.5px; }

/* ---------- 时间线（dominant） ---------- */

.timeline-pane { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--line); }

.timeline-scroll { overflow-y: auto; padding: 14px 18px 28px 18px; flex: 1; }

.day-sep {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-faint);
  font-size: 11px;
  letter-spacing: 1.5px;
  margin: 14px 0 8px;
}
.day-sep::after { content: ""; flex: 1; height: 1px; background: var(--line); }
.day-sep:first-child { margin-top: 0; }

.cs-node {
  position: relative;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--bg-raised);
  margin: 0 0 12px 22px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.cs-node::before {
  content: "";
  position: absolute;
  left: -27px;
  top: 18px;
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--bg);
  border: 2px solid var(--line-strong);
}
.cs-node::after {
  content: "";
  position: absolute;
  left: -23px;
  top: -14px;
  bottom: calc(100% - 18px);
  width: 2px;
  background: var(--line);
}
.cs-node:first-of-type::after { display: none; }

.cs-node.selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent), 0 0 18px rgba(76, 141, 255, 0.18);
}
.cs-node.selected::before { border-color: var(--accent); background: var(--accent); }

.cs-node.linked { border-color: var(--line-strong); box-shadow: 0 0 0 1px rgba(76, 141, 255, 0.25); }

.cs-node.muted { opacity: 0.42; }

.cs-node.flash { animation: flash 1.1s ease-out 2; }
@keyframes flash {
  0%, 100% { box-shadow: 0 0 0 1px transparent; }
  40% { box-shadow: 0 0 0 2px var(--amber), 0 0 22px rgba(210, 154, 58, 0.35); }
}
@media (prefers-reduced-motion: reduce) { .cs-node.flash { animation: none; box-shadow: 0 0 0 2px var(--amber); } }

.node-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 9px 12px 7px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}

.node-id { font-family: var(--mono); font-weight: 700; font-size: 13px; color: var(--text); }
.cs-node.selected .node-id { color: var(--accent); }

.node-title { font-weight: 600; }

.node-time { color: var(--text-dim); font-size: 12px; font-family: var(--mono); }

.node-author { color: var(--text-faint); font-size: 12px; }

.node-head-right { margin-left: auto; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }

.causal-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  border-radius: 5px;
  padding: 2px 7px;
  border: 1px solid transparent;
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-family: var(--mono);
}
.causal-badge.b-cause { color: var(--amber); border-color: rgba(210, 154, 58, 0.4); background: rgba(210, 154, 58, 0.08); }
.causal-badge.b-effect { color: var(--teal); border-color: rgba(58, 166, 185, 0.4); background: rgba(58, 166, 185, 0.08); }
.causal-badge:hover { filter: brightness(1.25); }

.node-body { padding: 6px 12px 8px; }

.chg {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 3.5px 0;
  font-size: 12.5px;
  min-width: 0;
}
.chg + .chg { border-top: 1px dashed rgba(39, 48, 64, 0.6); }
.chg.dim { opacity: 0.25; }

.chg .el { font-family: var(--mono); color: var(--text); flex: none; }
.chg .arrow { color: var(--text-faint); flex: none; }
.chg .val { font-family: var(--mono); color: var(--text-dim); }
.chg .val.after { color: var(--text); }
.chg .val.removed-mark { text-decoration: line-through; }
.chg .tail { color: var(--text-faint); font-size: 11.5px; margin-left: auto; padding-left: 8px; white-space: nowrap; }

.node-empty-note { color: var(--text-faint); font-size: 12px; padding: 4px 0; font-style: italic; }

/* 空态：筛选无任何匹配 */
.timeline-empty {
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  padding: 26px 20px;
  text-align: center;
  color: var(--text-dim);
  margin-left: 22px;
}
.timeline-empty strong { color: var(--amber); display: block; margin-bottom: 6px; font-size: 13px; }

/* ---------- 右侧详情 ---------- */

.side-pane {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.inspector {
  flex: 1.25;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}

.state-panel {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--text-faint);
  margin: 0 0 8px;
}
.section-label .accent-cause { color: var(--amber); }
.section-label .accent-effect { color: var(--teal); }

.insp-head { margin-bottom: 12px; }
.insp-head .line1 { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.insp-head .node-id { font-size: 15px; color: var(--accent); }
.insp-head .title { font-size: 14px; font-weight: 600; }
.insp-head .sub { margin: 3px 0 0; color: var(--text-dim); font-size: 12px; display: flex; gap: 10px; flex-wrap: wrap; }
.tag {
  display: inline-block;
  border: 1px solid var(--line-strong);
  color: var(--text-dim);
  border-radius: 4px;
  font-size: 11px;
  padding: 0 6px;
  margin-right: 4px;
}

.causal-block { margin-bottom: 14px; }

.causal-card {
  display: block;
  width: 100%;
  text-align: left;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 7px 10px;
  margin-bottom: 6px;
  cursor: pointer;
  color: var(--text);
  font: inherit;
}
.causal-card:hover { background: var(--bg-hover); border-color: var(--line-strong); }
.causal-card .cc-top { display: flex; gap: 8px; align-items: baseline; }
.causal-card .cc-id { font-family: var(--mono); font-weight: 700; font-size: 12px; }
.causal-card.b-cause .cc-id { color: var(--amber); }
.causal-card.b-effect .cc-id { color: var(--teal); }
.causal-card .cc-time { color: var(--text-faint); font-size: 11px; font-family: var(--mono); margin-left: auto; }
.causal-card .cc-reason { color: var(--text-dim); font-size: 12px; margin: 3px 0 0; }

.causal-none { color: var(--text-faint); font-size: 12px; font-style: italic; margin: 0; }

.insp-changes { display: flex; flex-direction: column; }
.insp-chg { border-top: 1px dashed rgba(39, 48, 64, 0.6); padding: 7px 0; }
.insp-chg:first-child { border-top: none; }
.insp-chg .row1 { display: flex; align-items: center; gap: 8px; }
.insp-chg .row1 .el { font-family: var(--mono); font-weight: 600; }
.insp-chg .row1 .el .to { color: var(--rename); }
.insp-chg .row1 .tail { margin-left: auto; }
.insp-chg .diff { display: flex; gap: 6px; flex-wrap: wrap; margin: 3px 0 0 25px; align-items: baseline; }
.insp-chg .diff .val { font-family: var(--mono); font-size: 12px; }
.insp-chg .diff .val.before { color: var(--text-dim); }
.insp-chg .diff .val.after { color: var(--text); }
.insp-chg .diff .val.before.strike { text-decoration: line-through; }
.insp-chg .note { margin: 2px 0 0 25px; color: var(--text-faint); font-size: 11.5px; }

/* ---------- 状态回放面板 ---------- */

.state-head {
  padding: 10px 16px 8px;
  border-bottom: 1px solid var(--line);
  flex: none;
}
.state-head h2 { margin: 0; font-size: 13px; font-weight: 600; }
.state-head .asof { color: var(--text-dim); font-size: 12px; margin: 3px 0 0; }
.state-head .asof .mono { font-family: var(--mono); color: var(--accent); }

.state-scroll { overflow-y: auto; flex: 1; padding: 8px 16px 16px; }

.state-table { width: 100%; border-collapse: collapse; }
.state-table th {
  text-align: left;
  font-size: 11px;
  letter-spacing: 1px;
  color: var(--text-faint);
  font-weight: 600;
  padding: 4px 8px;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: -8px;
  background: var(--bg);
}
.state-table td {
  padding: 4.5px 8px;
  border-bottom: 1px solid rgba(39, 48, 64, 0.5);
  font-family: var(--mono);
  font-size: 12px;
  vertical-align: top;
}
.state-table td.el-cell { color: var(--text); white-space: nowrap; }
.state-table td.val-cell { color: var(--text-dim); word-break: break-all; }
.state-table tr.touched td { background: var(--accent-soft); }
.state-table tr.touched td.el-cell { color: var(--text); }
.state-table tr.touched td.val-cell { color: var(--text); }
.state-table .removed { text-decoration: line-through; }
.state-table .removed-by { color: var(--remove); font-size: 11px; margin-left: 6px; font-family: var(--mono); }
.state-table .dot {
  display: inline-block; width: 6px; height: 6px; border-radius: 50%;
  background: var(--accent); margin-right: 6px; vertical-align: 1px;
}

/* ---------- 错误横幅 ---------- */

.app-error {
  position: fixed;
  inset: auto 18px 18px 18px;
  background: rgba(224, 89, 111, 0.12);
  border: 1px solid var(--remove);
  color: var(--text);
  border-radius: var(--radius);
  padding: 12px 16px;
  font-size: 13px;
  z-index: 50;
}

/* ---------- 滚动条 / 焦点 ---------- */

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--line-strong); border-radius: 5px; border: 2px solid var(--bg); }
::-webkit-scrollbar-track { background: transparent; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  border-radius: 4px;
}

button { -webkit-tap-highlight-color: transparent; }

