1	/* Orbit CDN · 变更时间线 —— 应用逻辑
2	 *
3	 * 设计约定（与验收种子对应）：
4	 *  - 时间结构：changeSets 按 ts 严格递增渲染，上早下晚；节点的视觉顺序 = 时间顺序。
5	 *  - 变更语义：因果徽标只允许指向「因=更早 / 果=更晚」；启动时校验 cause.ts < effect.ts。
6	 *  - 状态回放：replayTo 为纯函数，按时间升序逐条应用 change 至选中节点（含），
7	 *    与时间轴共用同一排序 —— 时间结构与变更语义由构造保证一致。
8	 *  - 状态清单：ready（首屏内联数据即就绪，按交付约束不存在加载态）、selected、
9	 *    empty（筛选无匹配）、error（渲染异常横幅）。
10	 */
11	(function () {
12	  'use strict';
13	
14	  var DATA = window.ORBIT_DATA;
15	
16	  var TYPE_META = {
17	    add:    { label: '新增',   symbol: '+', cls: 't-add' },
18	    modify: { label: '修改',   symbol: '~', cls: 't-modify' },
19	    remove: { label: '移除',   symbol: '−', cls: 't-remove' },
20	    rename: { label: '重命名', symbol: '→', cls: 't-rename' }
21	  };
22	
23	  /* ---------- 数据整理与完整性校验 ---------- */
24	
25	  var sets = DATA.changeSets.slice().sort(function (a, b) {
26	    return a.ts < b.ts ? -1 : a.ts > b.ts ? 1 : 0;
27	  });
28	  var byId = {};
29	  sets.forEach(function (s) { byId[s.id] = s; });
30	
31	  var integrityProblems = [];
32	  for (var i = 1; i < sets.length; i++) {
33	    if (!(sets[i - 1].ts < sets[i].ts)) {
34	      integrityProblems.push('时间序冲突：' + sets[i - 1].id + ' 不早于 ' + sets[i].id);
35	    }
36	  }
37	
38	  var linksByCause = {}, linksByEffect = {};
39	  DATA.causalLinks.forEach(function (l) {
40	    var c = byId[l.cause], e = byId[l.effect];
41	    if (!c || !e) {
42	      integrityProblems.push('因果链接 ' + l.id + ' 端点缺失');
43	      return;
44	    }
45	    if (!(c.ts < e.ts)) {
46	      integrityProblems.push('因果链接 ' + l.id + ' 违反时间方向：' + l.cause + ' 不早于 ' + l.effect);
47	    }
48	    (linksByCause[l.cause] = linksByCause[l.cause] || []).push(l);
49	    (linksByEffect[l.effect] = linksByEffect[l.effect] || []).push(l);
50	  });
51	  if (integrityProblems.length) {
52	    console.warn('[数据完整性] 时间/因果约束冲突：\n' + integrityProblems.join('\n'));
53	  }
54	
55	  var totalChanges = sets.reduce(function (n, s) { return n + s.changes.length; }, 0);
56	
57	  var allElements = {};
58	  sets.forEach(function (s) {
59	    s.changes.forEach(function (ch) {
60	      allElements[ch.element] = true;
61	      if (ch.to) allElements[ch.to] = true;
62	    });
63	  });
64	  var elementList = Object.keys(allElements).sort();
65	
66	  /* ---------- 状态（单一 store：selection + query） ---------- */
67	
68	  var state = {
69	    selectedId: sets[sets.length - 1].id, // 首屏默认选中最新变更集
70	    type: 'all',
71	    element: 'all'
72	  };
73	
74	  /* ---------- 工具 ---------- */
75	
76	  function esc(v) {
77	    return String(v == null ? '' : v)
78	      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
79	  }
80	
81	  function pad(n) { return (n < 10 ? '0' : '') + n; }
82	
83	  var WD = ['日', '一', '二', '三', '四', '五', '六'];
84	
85	  function parts(ts) {
86	    var d = new Date(ts);
87	    return {
88	      day: pad(d.getMonth() + 1) + '-' + pad(d.getDate()),
89	      weekday: '周' + WD[d.getDay()],
90	      time: pad(d.getHours()) + ':' + pad(d.getMinutes()),
91	      full: d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
92	        ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes())
93	    };
94	  }
95	
96	  function matches(ch) {
97	    if (state.type !== 'all' && ch.type !== state.type) return false;
98	    if (state.element !== 'all' && ch.element !== state.element && ch.to !== state.element) return false;
99	    return true;
100	  }
101	
102	  function changesMatchIn(cs) {
103	    return cs.changes.some(matches);
104	  }
105	
106	  /* 回放：按时间升序应用至 selectedId（含）。返回 Map<element, {value, removed, by}> */
107	  function replayTo(csId) {
108	    var target = byId[csId];
109	    var m = new Map();
110	    for (var i = 0; i < sets.length; i++) {
111	      var s = sets[i];
112	      if (s.ts > target.ts) break;
113	      s.changes.forEach(function (ch) {
114	        if (ch.type === 'add' || ch.type === 'modify') {
115	          m.set(ch.element, { value: ch.after, removed: false, by: s.id });
116	        } else if (ch.type === 'rename') {
117	          m.delete(ch.element);
118	          m.set(ch.to, { value: ch.after, removed: false, by: s.id });
119	        } else if (ch.type === 'remove') {
120	          m.set(ch.element, { value: null, removed: true, by: s.id });
121	        }
122	      });
123	    }
124	    return m;
125	  }
126	
127	  /* ---------- 渲染：时间线 ---------- */
128	
129	  function compactRow(ch) {
130	    var t = TYPE_META[ch.type];
131	    var html = '<div class="chg" data-chg="' + esc(ch.id) + '">' +
132	      '<i class="sym ' + t.cls + '" title="' + t.label + '">' + t.symbol + '</i>' +
133	      '<span class="el">' + esc(ch.element) + '</span>';
134	    if (ch.type === 'rename') {
135	      html += ' <span class="arrow">→</span> <span class="el">' + esc(ch.to) + '</span>' +
136	        ' <span class="arrow">·</span> <span class="val">' + esc(ch.before) + '</span>' +
137	        ' <span class="arrow">→</span> <span class="val after">' + esc(ch.after) + '</span>';
138	    } else if (ch.type === 'add') {
139	      html += ' <span class="arrow">=</span> <span class="val after">' + esc(ch.after) + '</span>';
140	    } else if (ch.type === 'remove') {
141	      html += ' <span class="val removed-mark">' + esc(ch.before) + '</span>' +
142	        ' <span class="arrow">→</span> <span class="val">已移除</span>';
143	    } else {
144	      html += ' <span class="val">' + esc(ch.before) + '</span>' +
145	        ' <span class="arrow">→</span> <span class="val after">' + esc(ch.after) + '</span>';
146	    }
147	    html += '</div>';
148	    return html;
149	  }
150	
151	  function causalBadges(csId) {
152	    var out = [];
153	    (linksByEffect[csId] || []).forEach(function (l) {
154	      out.push('<button type="button" class="causal-badge b-cause" data-jump="' + esc(l.cause) + '"' +
155	        ' title="跳转到因（更早）">' + '↩ 因 ' + esc(l.cause) + '</button>');
156	    });
157	    (linksByCause[csId] || []).forEach(function (l) {
158	      out.push('<button type="button" class="causal-badge b-effect" data-jump="' + esc(l.effect) + '"' +
159	        ' title="跳转到果（更晚）">' + '↪ 果 ' + esc(l.effect) + '</button>');
160	    });
161	    return out.join('');
162	  }
163	
164	  function renderTimeline() {
165	    var root = document.getElementById('timeline');
166	    var html = '';
167	    var lastDay = null;
168	    var anyRowVisible = false;
169	
170	    sets.forEach(function (s, idx) {
171	      var p = parts(s.ts);
172	      if (p.day !== lastDay) {
173	        lastDay = p.day;
174	        html += '<div class="day-sep">' + esc(p.day) + ' ' + esc(p.weekday) + '</div>';
175	      }
176	      var hasMatch = changesMatchIn(s);
177	      if (hasMatch) anyRowVisible = true;
178	      var linkedIds = causalNeighborIds(s.id);
179	      var cls = 'cs-node' +
180	        (s.id === state.selectedId ? ' selected' : '') +
181	        (linkedIds ? ' linked' : '') +
182	        (hasMatch ? '' : ' muted');
183	      html += '<article class="' + cls + '" role="listitem" data-cs="' + esc(s.id) + '"' +
184	        ' tabindex="-1" aria-current="' + (s.id === state.selectedId) + '">' +
185	        '<div class="node-head">' +
186	          '<span class="node-id">' + esc(s.id) + '</span>' +
187	          '<span class="node-title">' + esc(s.title) + '</span>' +
188	          '<span class="node-time">' + esc(p.day) + ' ' + esc(p.time) + '</span>' +
189	          '<span class="node-author">@' + esc(s.author) + '</span>' +
190	          '<span class="node-head-right">' + causalBadges(s.id) + '</span>' +
191	        '</div>' +
192	        '<div class="node-body">' +
193	          (hasMatch
194	            ? s.changes.filter(matches).map(compactRow).join('')
195	            : '<p class="node-empty-note">当前筛选下无匹配变更</p>') +
196	        '</div>' +
197	      '</article>';
198	    });
199	
200	    if (!anyRowVisible) {
201	      html = '<div class="timeline-empty" role="status">' +
202	        '<strong>当前筛选无任何匹配变更</strong>' +
203	        '时间线结构保持完整显示（已置灰）。调整或清除筛选以查看变更明细。' +
204	        '</div>';
205	    }
206	    root.innerHTML = html;
207	    root.setAttribute('aria-label', '变更集序列，共 ' + sets.length + ' 个，按时间升序');
208	  }
209	
210	  function causalNeighborIds(csId) {
211	    var ids = [];
212	    (linksByCause[csId] || []).forEach(function (l) { ids.push(l.effect); });
213	    (linksByEffect[csId] || []).forEach(function (l) { ids.push(l.cause); });
214	    return ids;
215	  }
216	
217	  /* ---------- 渲染：选中详情 ---------- */
218	
219	  function detailRow(ch) {
220	    var t = TYPE_META[ch.type];
221	    var elHtml = esc(ch.element);
222	    if (ch.type === 'rename') {
223	      elHtml += ' <span class="arrow">→</span> <span class="to">' + esc(ch.to) + '</span>';
224	    }
225	    var diff = '';
226	    if (ch.type === 'add') {
227	      diff = '<span class="val after">' + esc(ch.after) + '</span>';
228	    } else if (ch.type === 'remove') {
229	      diff = '<span class="val before strike">' + esc(ch.before) + '</span>' +
230	        '<span class="arrow">→</span><span class="val">已移除</span>';
231	    } else if (ch.type === 'rename') {
232	      diff = '<span class="val before">' + esc(ch.before) + '</span>' +
233	        '<span class="arrow">→</span><span class="val after">' + esc(ch.after) + '</span>';
234	    } else {
235	      diff = '<span class="val before">' + esc(ch.before) + '</span>' +
236	        '<span class="arrow">→</span><span class="val after">' + esc(ch.after) + '</span>';
237	    }
238	    return '<div class="insp-chg">' +
239	      '<div class="row1"><i class="sym ' + t.cls + '" title="' + t.label + '">' + t.symbol + '</i>' +
240	      '<span class="el">' + elHtml + '</span>' +
241	      '<span class="tail node-author">' + t.label + '</span></div>' +
242	      '<div class="diff">' + diff + '</div>' +
243	      (ch.note ? '<p class="note">' + esc(ch.note) + '</p>' : '') +
244	    '</div>';
245	  }
246	
247	  function causalCard(l, dir) {
248	    var other = dir === 'cause' ? l.cause : l.effect;
249	    var s = byId[other];
250	    return '<button type="button" class="causal-card b-' + (dir === 'cause' ? 'cause' : 'effect') + '" data-jump="' + esc(other) + '">' +
251	      '<span class="cc-top"><span class="cc-id">' + esc(other) + '</span>' +
252	      '<span class="cc-time">' + esc(parts(s.ts).day + ' ' + parts(s.ts).time) + '</span></span>' +
253	      '<span class="cc-reason">' + esc(l.reason) + '</span>' +
254	    '</button>';
255	  }
256	
257	  function renderInspector() {
258	    var root = document.getElementById('region-inspector');
259	    var s = byId[state.selectedId];
260	    var p = parts(s.ts);
261	    var causes = (linksByEffect[s.id] || []);
262	    var effects = (linksByCause[s.id] || []);
263	
264	    root.innerHTML =
265	      '<div class="insp-head">' +
266	        '<div class="line1"><span class="node-id">' + esc(s.id) + '</span>' +
267	        '<span class="title">' + esc(s.title) + '</span></div>' +
268	        '<p class="sub"><span>' + esc(p.full) + '</span><span>@' + esc(s.author) + '</span>' +
269	        '<span>触发：' + esc(s.trigger) + '</span>' +
270	        '<span>' + s.tags.map(function (t) { return '<span class="tag">' + esc(t) + '</span>'; }).join('') + '</span></p>' +
271	      '</div>' +
272	      '<div class="causal-block">' +
273	        '<p class="section-label"><span class="accent-cause">↩ 因何发生</span>（指向更早）</p>' +
274	        (causes.length ? causes.map(function (l) { return causalCard(l, 'cause'); }).join('')
275	                       : '<p class="causal-none">无记录的因（窗口内起点）</p>') +
276	      '</div>' +
277	      '<div class="causal-block">' +
278	        '<p class="section-label"><span class="accent-effect">↪ 引发</span>（指向更晚）</p>' +
279	        (effects.length ? effects.map(function (l) { return causalCard(l, 'effect'); }).join('')
280	                        : '<p class="causal-none">无记录的果（窗口内终点）</p>') +
281	      '</div>' +
282	      '<p class="section-label">变更明细 · ' + s.changes.length + ' 条</p>' +
283	      '<div class="insp-changes">' + s.changes.map(detailRow).join('') + '</div>';
284	  }
285	
286	  /* ---------- 渲染：状态回放 ---------- */
287	
288	  function renderStatePanel() {
289	    var root = document.getElementById('region-state-panel');
290	    var s = byId[state.selectedId];
291	    var p = parts(s.ts);
292	    var snap = replayTo(s.id);
293	
294	    var touched = {};
295	    s.changes.forEach(function (ch) {
296	      touched[ch.element] = true;
297	      if (ch.to) touched[ch.to] = true;
298	    });
299	
300	    var keys = Array.from(snap.keys()).sort();
301	    var rows = keys.map(function (k) {
302	      var v = snap.get(k);
303	      var valHtml;
304	      if (v.removed) {
305	        valHtml = '<span class="removed">（无值）</span><span class="removed-by">已移除 @' + esc(v.by) + '</span>';
306	      } else {
307	        valHtml = esc(v.value);
308	      }
309	      return '<tr class="' + (touched[k] ? 'touched' : '') + '">' +
310	        '<td class="el-cell">' + (touched[k] ? '<span class="dot" title="被选中变更集作用"></span>' : '') + esc(k) + '</td>' +
311	        '<td class="val-cell">' + valHtml + '</td>' +
312	      '</tr>';
313	    }).join('');
314	
315	    root.innerHTML =
316	      '<div class="state-head">' +
317	        '<h2>状态快照 <span class="pane-sub">回放至选中时刻</span></h2>' +
318	        '<p class="asof">截至 <span class="mono">' + esc(s.id) + '</span> · ' + esc(p.full) +
319	        ' · 已按时间序应用 <span class="mono">' + appliedCount(s.id) + '</span> 条变更 · 元素 <span class="mono">' + keys.length + '</span> 个</p>' +
320	      '</div>' +
321	      '<div class="state-scroll"><table class="state-table">' +
322	        '<thead><tr><th>元素</th><th>当前值</th></tr></thead>' +
323	        '<tbody>' + rows + '</tbody>' +
324	      '</table></div>';
325	  }
326	
327	  function appliedCount(csId) {
328	    var target = byId[csId], n = 0;
329	    sets.forEach(function (s) {
330	      if (s.ts <= target.ts) n += s.changes.length;
331	    });
332	    return n;
333	  }
334	
335	  /* ---------- 渲染：筛选行 / 头部 ---------- */
336	
337	  function renderFilters() {
338	    var chipsRoot = document.getElementById('type-chips');
339	    var defs = [['all', '全部'], ['add', '新增'], ['modify', '修改'], ['remove', '移除'], ['rename', '重命名']];
340	    chipsRoot.innerHTML = defs.map(function (d) {
341	      return '<button type="button" class="chip" data-type="' + d[0] + '" aria-pressed="' + (state.type === d[0]) + '">' + d[1] + '</button>';
342	    }).join('');
343	
344	    var sel = document.getElementById('element-select');
345	    sel.innerHTML = '<option value="all">全部元素</option>' + elementList.map(function (e) {
346	      return '<option value="' + esc(e) + '"' + (state.element === e ? ' selected' : '') + '>' + esc(e) + '</option>';
347	    }).join('');
348	
349	    var active = state.type !== 'all' || state.element !== 'all';
350	    document.getElementById('clear-filters').hidden = !active;
351	
352	    var note = document.getElementById('filter-note');
353	    var visibleRows = 0;
354	    sets.forEach(function (s) { s.changes.forEach(function (ch) { if (matches(ch)) visibleRows++; }); });
355	    if (!active) {
356	      note.textContent = '显示全部 ' + visibleRows + ' 条变更';
357	      note.className = 'filter-note';
358	    } else if (visibleRows === 0) {
359	      note.textContent = '无匹配变更（0/' + totalChanges + '）';
360	      note.className = 'filter-note warn';
361	    } else {
362	      note.textContent = '筛选中：显示 ' + visibleRows + ' / ' + totalChanges + ' 条变更';
363	      note.className = 'filter-note' + (visibleRows < totalChanges ? ' warn' : '');
364	    }
365	  }
366	
367	  function renderHeader() {
368	    var first = parts(sets[0].ts), last = parts(sets[sets.length - 1].ts);
369	    document.getElementById('header-meta').textContent =
370	      DATA.windowLabel + ' · ' + sets.length + ' 个变更集 · ' + totalChanges + ' 条变更 · ' +
371	      DATA.causalLinks.length + ' 条因果链接 · ' + first.day + ' → ' + last.day;
372	  }
373	
374	  function renderAll() {
375	    renderHeader();
376	    renderFilters();
377	    renderTimeline();
378	    renderInspector();
379	    renderStatePanel();
380	  }
381	
382	  /* ---------- 交互 ---------- */
383	
384	  function select(csId, opts) {
385	    if (!byId[csId]) return;
386	    state.selectedId = csId;
387	    renderTimeline();
388	    renderInspector();
389	    renderStatePanel();
390	    var node = document.querySelector('.cs-node[data-cs="' + csId + '"]');
391	    if (node) {
392	      if (opts && opts.center) {
393	        node.scrollIntoView({ block: 'center', behavior: 'smooth' });
394	      } else {
395	        node.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
396	      }
397	      if (opts && opts.flash) {
398	        node.classList.remove('flash');
399	        void node.offsetWidth; // 重新触发动画
400	        node.classList.add('flash');
401	      }
402	    }
403	  }
404	
405	  function jump(csId) { select(csId, { center: true, flash: true }); }
406	
407	  document.getElementById('timeline').addEventListener('click', function (ev) {
408	    var badge = ev.target.closest('.causal-badge');
409	    if (badge) {
410	      jump(badge.getAttribute('data-jump'));
411	      return;
412	    }
413	    var node = ev.target.closest('.cs-node');
414	    if (node) select(node.getAttribute('data-cs'));
415	  });
416	
417	  document.getElementById('region-inspector').addEventListener('click', function (ev) {
418	    var card = ev.target.closest('.causal-card');
419	    if (card) jump(card.getAttribute('data-jump'));
420	  });
421	
422	  document.getElementById('type-chips').addEventListener('click', function (ev) {
423	    var chip = ev.target.closest('.chip');
424	    if (!chip) return;
425	    state.type = chip.getAttribute('data-type');
426	    renderFilters();
427	    renderTimeline();
428	  });
429	
430	  document.getElementById('element-select').addEventListener('change', function (ev) {
431	    state.element = ev.target.value;
432	    renderFilters();
433	    renderTimeline();
434	  });
435	
436	  function clearFilters() {
437	    state.type = 'all';
438	    state.element = 'all';
439	    renderFilters();
440	    renderTimeline();
441	  }
442	  document.getElementById('clear-filters').addEventListener('click', clearFilters);
443	
444	  document.addEventListener('keydown', function (ev) {
445	    if (ev.target && (ev.target.tagName === 'SELECT' || ev.target.tagName === 'INPUT' || ev.target.tagName === 'TEXTAREA')) return;
446	    if (ev.key === 'Escape') { clearFilters(); return; }
447	    if (ev.key !== 'ArrowUp' && ev.key !== 'ArrowDown') return;
448	    ev.preventDefault();
449	    var idx = sets.findIndex(function (s) { return s.id === state.selectedId; });
450	    var next = ev.key === 'ArrowUp' ? idx - 1 : idx + 1;
451	    if (next < 0 || next >= sets.length) return;
452	    select(sets[next].id);
453	  });
454	
455	  /* ---------- 启动：内联数据随脚本就绪，无加载态 ---------- */
456	
457	  try {
458	    renderAll();
459	    if (integrityProblems.length) {
460	      var err = document.getElementById('app-error');
461	      err.hidden = false;
462	      err.textContent = '数据完整性告警：' + integrityProblems.join('；');
463	    }
464	  } catch (e) {
465	    var err = document.getElementById('app-error');
466	    err.hidden = false;
467	    err.textContent = '渲染失败：' + (e && e.message ? e.message : e);
468	    throw e;
469	  }
470	})();
